window.LD=window.LD||{};window.LD["headlines"]={"1":[{"id":"e1","day":1,"season":1,"sday":1,"kind":"season_start","imp":5,"text":"Season 1 is open, and it's the Bandit Summer: the roads are crawling, escort contracts pay well, and the fences in Carrbridge are busy.","heroes":[],"parties":[]},{"id":"e16","day":1,"season":1,"sday":1,"kind":"weather","imp":2,"text":"The west vanishes into fog. Somewhere in it, Griffin hums loudly, hoping to stay off the menu.","heroes":["h5","h8"],"parties":[],"loc":"hollowood"},{"id":"e18","day":1,"season":1,"sday":1,"kind":"legend","imp":4,"text":"An afternoon with Brother Toad, Keeper of the Long Road, leaves Allie sore all over in Saltmarrow, and noticeably better for it.","heroes":["h4"],"parties":[],"loc":"saltmarrow","legend":"Brother Toad"},{"id":"e19","day":1,"season":1,"sday":1,"kind":"ambush","imp":3,"text":"A rough start on the road to Veldrock: a Bandit Captain and a Wolf overwhelm Mark, who limps off with a cracked collarbone.","heroes":["h14"],"parties":[],"loc":"kingsroad"},{"id":"e20","day":1,"season":1,"sday":1,"kind":"night","imp":2,"text":"An old pilgrim stops at Mark's camp on the road to Veldrock and swears there's treasure left in the Wolf Den. Everyone pretends not to be interested.","heroes":["h14"],"parties":[],"loc":"ironhaven"},{"id":"e21","day":1,"season":1,"sday":1,"kind":"ambush","imp":2,"text":"Corrine beats a Bandit on the road to Saltmarrow. Loot: 1 bag of stolen goods.","heroes":["h7"],"parties":[],"loc":"kingsroad"},{"id":"e22","day":1,"season":1,"sday":1,"kind":"party_formed","imp":4,"text":"Handshakes at The Gilded Flagon: Mark and Ryan are now The Black Pack, and an honorable-looking outfit at that.","heroes":["h14","h3"],"parties":["p1"],"loc":"ironhaven"}],"2":[{"id":"e25","day":2,"season":1,"sday":2,"kind":"ambush","imp":3,"text":"First blood for Troy: he sees off a Wolf on the road to Thornwall and walks away with 1 pelt and 2 fangs & claws.","heroes":["h8"],"parties":[],"loc":"kingsroad"},{"id":"e26","day":2,"season":1,"sday":2,"kind":"contract","imp":3,"text":"First job for Andrew: he takes the poster down in Thornwall. Mother Mire is his. Or will be.","heroes":["h2"],"parties":[],"loc":"thornwall"},{"id":"e27","day":2,"season":1,"sday":2,"kind":"ambush","imp":3,"text":"First blood for Andrew, on the King's Road: a Bandit Archer and a Bandit go down, and he comes away with 1 bag of stolen goods.","heroes":["h2"],"parties":[],"loc":"kingsroad"},{"id":"e29","day":2,"season":1,"sday":2,"kind":"cooking","imp":2,"text":"Matt cooks Rat-on-a-Stick over the fire in the Collapsed Mine. It is better than it has any right to be.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e30","day":2,"season":1,"sday":2,"kind":"fight","imp":3,"text":"First blood for Matt, on floor 1 of the Collapsed Mine: a Giant Rat and a Kobold, dispatched. The haul: 1 fang and 1 trinket.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e31","day":2,"season":1,"sday":2,"kind":"contract","imp":3,"text":"First job for Joshua: he takes down a poster in Thornwall too. Mother Mire is his. Or will be.","heroes":["h11"],"parties":[],"loc":"thornwall"},{"id":"e32","day":2,"season":1,"sday":2,"kind":"ambush","imp":3,"text":"First blood for Cade: he makes short work of a Bandit Archer on the road to Ironhaven and pockets 1 bag of stolen goods.","heroes":["h13"],"parties":[],"loc":"kingsroad"},{"id":"e33","day":2,"season":1,"sday":2,"kind":"ambush","imp":3,"text":"A Bandit Captain catches Keenan on the road to Ironhaven, and Keenan does the sensible thing: he runs for it.","heroes":["h9"],"parties":[],"loc":"kingsroad"},{"id":"e34","day":2,"season":1,"sday":2,"kind":"party_join","imp":3,"text":"Olivia joins The Black Pack over drinks in Veldrock. Mark and Ryan have company now: that makes 3.","heroes":["h10","h14","h3"],"parties":["p1"],"loc":"veldrock"},{"id":"e35","day":2,"season":1,"sday":2,"kind":"party_formed","imp":4,"text":"Keenan and Cade shake on it at The Gilded Flagon: they are now The Royal Shadows. Honourable, by the look of them.","heroes":["h9","h13"],"parties":["p2"],"loc":"ironhaven"},{"id":"e36","day":2,"season":1,"sday":2,"kind":"rescue","imp":4,"text":"Joshua pulls Andrew out of trouble on the King's Road, 1 potion poorer for it. Andrew owes him a life now.","heroes":["h11","h2"],"parties":[],"loc":"kingsroad"},{"id":"e37","day":2,"season":1,"sday":2,"kind":"vow","imp":3,"text":"Andrew owes Joshua a life, and has sworn to repay it. \"He didn't have to stop for me. I won't forget that,\" says Andrew.","heroes":["h2"],"parties":[],"cause":"e36"},{"id":"e38","day":2,"season":1,"sday":2,"kind":"meet","imp":2,"text":"The Black Pack and Keenan pass on the road between Ironhaven and Veldrock. There is a short argument about the best road to Thornwall.","heroes":["h14","h3","h10","h9"],"parties":["p1"],"loc":"ironhaven"},{"id":"e40","day":2,"season":1,"sday":2,"kind":"epithet","imp":3,"text":"A day after he pulled Andrew off the King's Road, the children of the street are calling Joshua \"Lifeline\". The grown-ups are not far behind.","heroes":["h11"],"parties":[]},{"id":"e41","day":2,"season":1,"sday":2,"kind":"treasure","imp":3,"text":"At an old adventurers' campfire outside Emberdeep, long gone cold, Jeff finds what its last owner left behind: a pack with 70 silver, two potions and a battered road journal. Jeff reads it cover to cover by the embers.","heroes":["h12"],"parties":[],"loc":"emberdeep"}],"3":[{"id":"e45","day":3,"season":1,"sday":3,"kind":"legend","imp":4,"text":"Old Marrow, the Last of the Ninefold, challenges Harry to a friendly duel in Frosthold. Harry lasts longer than most and walks away knowing more than he did.","heroes":["h1"],"parties":[],"loc":"frosthold","legend":"Old Marrow"},{"id":"e46","day":3,"season":1,"sday":3,"kind":"contract","imp":3,"text":"First job for Mark, Ryan and Olivia: the guild in Veldrock hires The Black Pack to walk lamp oil to Ironhaven. 32 silver each, if it all arrives.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"veldrock"},{"id":"e47","day":3,"season":1,"sday":3,"kind":"fight","imp":3,"text":"Mother Mire overwhelms Joshua on the King's Road. He comes away with a broken leg.","heroes":["h11"],"parties":[],"loc":"kingsroad"},{"id":"e48","day":3,"season":1,"sday":3,"kind":"vow_kept","imp":5,"text":"VOW KEPT. Andrew swore on day 2 to repay Joshua, and on day 3 he pulls Joshua out of trouble. \"He'd have done it for me. He did do it for me,\" says Andrew.","heroes":["h2"],"parties":[],"cause":"e37"},{"id":"e49","day":3,"season":1,"sday":3,"kind":"rescue","imp":5,"text":"Two days, two rescues on the King's Road, and the same two men. Andrew and Joshua have nothing left to owe each other, so they've settled on being friends for life instead.","heroes":["h2","h11"],"parties":[],"loc":"kingsroad","cause":"e36"},{"id":"e50","day":3,"season":1,"sday":3,"kind":"contract","imp":3,"text":"Mother Mire is everything the poster promised, and more. Joshua escapes with his life and none of the bounty.","heroes":["h11"],"parties":[],"loc":"kingsroad"},{"id":"e51","day":3,"season":1,"sday":3,"kind":"night","imp":2,"text":"Joshua limps after strange lights away from the camp on the King's Road, gets thoroughly lost, and has to be fetched back at dawn.","heroes":["h11"],"parties":[],"loc":"kingsroad"},{"id":"e53","day":3,"season":1,"sday":3,"kind":"town","imp":2,"text":"A pickpocket in Carrbridge picks the wrong mark. Griffin catches the hand mid-pocket and marches the kid to Toll-Captain Venn, who pays 5 silver for the trouble.","heroes":["h5"],"parties":[],"loc":"carrbridge"},{"id":"e56","day":3,"season":1,"sday":3,"kind":"party_formed","imp":4,"text":"Allie and Katie shake on it at The Honest Toll: they are now The Pack of Carrbridge. Honourable, by the look of them.","heroes":["h4","h16"],"parties":["p3"],"loc":"carrbridge"},{"id":"e57","day":3,"season":1,"sday":3,"kind":"party_join","imp":3,"text":"Joshua joins The Royal Shadows around the campfire on the King's Road, broken leg and all. That makes 3.","heroes":["h11","h9","h13"],"parties":["p2"],"loc":"kingsroad"},{"id":"e58","day":3,"season":1,"sday":3,"kind":"party_formed","imp":4,"text":"Amanda and Troy shake on it at The Sagging Beam: they are now Tidal Riders. Honourable, by the look of them.","heroes":["h17","h8"],"parties":["p4"],"loc":"thornwall"},{"id":"e59","day":3,"season":1,"sday":3,"kind":"campfire","imp":2,"text":"Ryan offers Mark the dry side of the tent. Mark accepts, suspiciously.","heroes":["h3","h14"],"parties":["p1"],"loc":"veldrock"},{"id":"e61","day":3,"season":1,"sday":3,"kind":"epithet","imp":3,"text":"Children in the street have started calling Andrew \"the Rescuer\". The grown-ups are not far behind.","heroes":["h2"],"parties":[]},{"id":"e62","day":3,"season":1,"sday":3,"kind":"folk","imp":2,"text":"Captain Brine (retired) at The Drowned Gull watches Corrine nurse one drink for an hour, then leans over the bar: \"The ones you're after went inland, to Carrbridge. Nice enough lot. You'd fit.\" Corrine leaves a coin and a thank-you.","heroes":["h7"],"parties":[],"loc":"saltmarrow"}],"4":[{"id":"e64","day":4,"season":1,"sday":4,"kind":"party_life","imp":2,"text":"The Royal Shadows talk about turning back for Joshua's broken leg, briefly. Then keep going.","heroes":["h9","h13","h11"],"parties":["p2"],"loc":"kingsroad"},{"id":"e65","day":4,"season":1,"sday":4,"kind":"fight","imp":3,"text":"First blood for Keenan: The Royal Shadows see off a Wolf, a Bandit Archer and a Bandit on the King's Road. Joshua did the unglamorous work that kept the line from breaking. Loot: 1 fang, 2 stolen goods.","heroes":["h9","h13","h11"],"parties":["p2"],"loc":"kingsroad"},{"id":"e67","day":4,"season":1,"sday":4,"kind":"night","imp":2,"text":"Something sings in the dark on the King's Road. Keenan goes to look and comes back with a trinket and a very quiet manner.","heroes":["h9","h13","h11"],"parties":["p2"],"loc":"kingsroad"},{"id":"e68","day":4,"season":1,"sday":4,"kind":"bodies","imp":2,"text":"Jeff wraps a dead bandit in an old blanket and ties it to his pack.","heroes":["h12"],"parties":[],"loc":"kingsroad"},{"id":"e69","day":4,"season":1,"sday":4,"kind":"ambush","imp":3,"text":"First blood for Jeff: one Bandit, beaten on the road to Veldrock. The spoils: 1 ration.","heroes":["h12"],"parties":[],"loc":"kingsroad"},{"id":"e71","day":4,"season":1,"sday":4,"kind":"contract","imp":2,"text":"The Black Pack walks lamp oil from Veldrock to Ironhaven without incident and collects 32 silver each. Boring. Paid.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"ironhaven"},{"id":"e74","day":4,"season":1,"sday":4,"kind":"party_formed","imp":4,"text":"Harry and Jeff shake on it at The Pickaxe & Pint: they are now The Green Hammers. Predatory, by the look of them.","heroes":["h1","h12"],"parties":["p5"],"loc":"veldrock"},{"id":"e75","day":4,"season":1,"sday":4,"kind":"party_join","imp":3,"text":"Andrew joins The Royal Shadows around the campfire on the King's Road. That makes 4, and the friends for life are now on the same side of the fire.","heroes":["h2","h9","h13","h11"],"parties":["p2"],"loc":"kingsroad"},{"id":"e77","day":4,"season":1,"sday":4,"kind":"campfire","imp":2,"text":"Troy and Amanda discover they grew up three valleys apart. The conversation lasts longer than either expected.","heroes":["h8","h17"],"parties":["p4"],"loc":"ironhaven"}],"5":[{"id":"e79","day":5,"season":1,"sday":5,"kind":"bounty_head","imp":3,"text":"Word on the road: somebody has put a price on Andrew's head. That's what leading the table gets you.","heroes":["h2"],"parties":[]},{"id":"e80","day":5,"season":1,"sday":5,"kind":"bounty_head","imp":3,"text":"Word on the road: somebody has put a price on Matt's head too. The top of the table is a target.","heroes":["h15"],"parties":[]},{"id":"e82","day":5,"season":1,"sday":5,"kind":"delve_done","imp":2,"text":"Matt comes up after 4 days in the Collapsed Mine: down to floor 2, his map now covers 42% of it, disarmed 2 traps and 11 silver richer. Counting everyone's digging, the Collapsed Mine is mostly unexplored (22%).","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e83","day":5,"season":1,"sday":5,"kind":"contract","imp":3,"text":"First job for Harry and Jeff: a nameless man in Veldrock pays The Green Hammers to move three sacks of what are definitely not stolen candlesticks to Saltmarrow. Half now, half on arrival, no questions.","heroes":["h1","h12"],"parties":["p5"],"loc":"veldrock"},{"id":"e84","day":5,"season":1,"sday":5,"kind":"fight","imp":2,"text":"The Royal Shadows beat 2 Bandit Archers, 2 Bandit Captains and a Wolf on the King's Road. Loot: 9 stolen goods, 1 gem, 1 fang.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"kingsroad"},{"id":"e86","day":5,"season":1,"sday":5,"kind":"town","imp":2,"text":"A pickpocket in Ironhaven picks the wrong mark. Olivia catches the hand mid-pocket and marches the kid to Captain Ysolde, who pays 5 silver for the trouble.","heroes":["h10"],"parties":[],"loc":"ironhaven"},{"id":"e87","day":5,"season":1,"sday":5,"kind":"meet","imp":2,"text":"The Royal Shadows and Griffin share a fire on the King's Road and trade news.","heroes":["h9","h13","h11","h2","h5"],"parties":["p2"],"loc":"kingsroad"},{"id":"e88","day":5,"season":1,"sday":5,"kind":"argument","imp":2,"text":"Ryan and Mark of The Black Pack have a shouting match about who lost the map.","heroes":["h3","h14"],"parties":["p1"]}],"6":[{"id":"e91","day":6,"season":1,"sday":6,"kind":"map_sale","imp":2,"text":"Matt sells a map of the Collapsed Mine to the Veldrock mapmaker for 11 silver. It shows 42% of the place, every trap marked.","heroes":["h15"],"parties":[],"loc":"veldrock"},{"id":"e92","day":6,"season":1,"sday":6,"kind":"fight","imp":3,"text":"Two Bandit Captains rout the Tidal Riders on the King's Road, and Amanda and Troy beat a hasty retreat. \"Run! Why aren't we running?\" Troy asks, already running.","heroes":["h17","h8"],"parties":["p4"],"loc":"kingsroad"},{"id":"e93","day":6,"season":1,"sday":6,"kind":"party_join","imp":3,"text":"Griffin joins the Tidal Riders around a campfire on the King's Road, making them three strong after a rough day.","heroes":["h5","h17","h8"],"parties":["p4"],"loc":"kingsroad"},{"id":"e94","day":6,"season":1,"sday":6,"kind":"argument","imp":2,"text":"Harry and Jeff of The Green Hammers have a shouting match about the ethics of looting bodies.","heroes":["h1","h12"],"parties":["p5"]}],"7":[{"id":"e97","day":7,"season":1,"sday":7,"kind":"contract","imp":2,"text":"A back door in Saltmarrow, a knock, a purse: The Green Hammers deliver three sacks of what are definitely not stolen candlesticks and collect 74 each. The less said the better.","heroes":["h1","h12"],"parties":["p5"],"loc":"saltmarrow"},{"id":"e101","day":7,"season":1,"sday":7,"kind":"town","imp":3,"text":"A Thornwall pickpocket picks the wrong mark: Andrew catches the hand mid-pocket and marches the kid to Sergeant Brask, who pays 5 silver for the trouble.","heroes":["h2"],"parties":[],"loc":"thornwall"},{"id":"e102","day":7,"season":1,"sday":7,"kind":"town","imp":3,"text":"For 10 silver, a stranger in Carrbridge sells Corrine a treasure map pointing to Frostspire. It might even be real.","heroes":["h7"],"parties":[],"loc":"carrbridge"},{"id":"e107","day":7,"season":1,"sday":7,"kind":"aside","imp":3,"text":"Deep water comes up at supper, just in passing. Katie goes very quiet and finds a reason to take the first watch.","heroes":["h16"],"parties":[],"loc":"kingsroad"}],"8":[{"id":"e111","day":8,"season":1,"sday":8,"kind":"ambush","imp":3,"text":"First blood for Harry: The Green Hammers beat a Drake, a Cliff Crab and a Bandit on the road to the Salt Cliffs, and Harry went in first without waiting to be asked. Jeff is already telling it as one against ten; it was two against three. \"Leave the heads,\" says Harry. Loot: 2 chitin, 3 fish, 1 bag of stolen goods.","heroes":["h1","h12"],"parties":["p5"],"loc":"saltcliffs"},{"id":"e112","day":8,"season":1,"sday":8,"kind":"talent","imp":2,"text":"Jeff says a quiet grace over the fire. Harry, who isn't religious, bows anyway.","heroes":["h12","h1"],"parties":["p5"],"loc":"saltcliffs"},{"id":"e115","day":8,"season":1,"sday":8,"kind":"ambush","imp":2,"text":"Matt handles a Kobold at their camp in the Collapsed Mine, in the middle of the night. Loot: 3 ore, 1 trinket.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e116","day":8,"season":1,"sday":8,"kind":"contract","imp":3,"text":"First job for Amanda, Troy and Griffin: Tidal Riders agree to fetch a sealed ledger from floor 1 of Goblin Camp. The family is very insistent.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"ironhaven"},{"id":"e117","day":8,"season":1,"sday":8,"kind":"fight","imp":3,"text":"First blood for Allie and Katie: The Pack of Carrbridge routs a Bandit Captain, a Wolf and a Bandit Archer on the King's Road and comes away with 6 stolen goods and 1 fang.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e118","day":8,"season":1,"sday":8,"kind":"fight","imp":3,"text":"First blood for Mark, Ryan and Olivia: The Black Pack sees off 2 Bandits on the King's Road. Loot: 4 stolen goods, 1 ration, 1 trinket.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"kingsroad"},{"id":"e119","day":8,"season":1,"sday":8,"kind":"contract","imp":3,"text":"First job for Corrine: the guild in Carrbridge hires her to walk bolts of cloth to Hollowood, at 41 silver each, if it all arrives.","heroes":["h7"],"parties":[],"loc":"carrbridge"},{"id":"e121","day":8,"season":1,"sday":8,"kind":"pet","imp":2,"text":"Pepper follows Rufus everywhere today. Allie says it's a phase. Katie says it's love.","heroes":["h16","h4"],"parties":[],"loc":"kingsroad"}],"9":[{"id":"e127","day":9,"season":1,"sday":9,"kind":"underdog","imp":3,"text":"From the bottom of the table, Griffin (16th of 17) is still swinging. Remember day 8, when Amanda, Troy and Griffin took the Tidal Riders' first job: a sealed ledger from floor 1 of Goblin Camp. Don't count him out.","heroes":["h5"],"parties":[]},{"id":"e129","day":9,"season":1,"sday":9,"kind":"weather","imp":2,"text":"The sky over the east turns the colour of a bruise. Harry pulls up a hood and keeps walking.","heroes":["h1"],"parties":[],"loc":"saltmarrow"},{"id":"e132","day":9,"season":1,"sday":9,"kind":"talent","imp":2,"text":"Mark beats a dent out of Olivia's helmet on a flat rock. It fits better than it did new.","heroes":["h14","h10"],"parties":["p1"],"loc":"kingsroad"},{"id":"e133","day":9,"season":1,"sday":9,"kind":"odd_job","imp":3,"text":"Odd job, odd ending: walking the wall for Captain Ysolde, Morgan turns up a roll of clean bandages, long lost. Captain Ysolde insisted Morgan keep it, and told the whole street why.","heroes":["h18"],"parties":[],"loc":"ironhaven"},{"id":"e134","day":9,"season":1,"sday":9,"kind":"fight","imp":2,"text":"The Pack of Carrbridge beats 2 Bandit Captains and a Bandit on the King's Road. Katie's Cleave did the damage (2 times). Loot: 10 stolen goods, 3 rations, 1 gem.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e135","day":9,"season":1,"sday":9,"kind":"talent","imp":2,"text":"Allie hangs three tiny flames over camp like lanterns. Katie reads by one until late.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e136","day":9,"season":1,"sday":9,"kind":"fight","imp":3,"text":"The Royal Shadows defeat 5 Wolves on the King's Road, with Cade calling out every flank before it turned. Loot: 3 pelts, 3 fangs & claws.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"kingsroad"},{"id":"e137","day":9,"season":1,"sday":9,"kind":"companion","imp":2,"text":"On the road to Hollowood, Corrine falls in with Osk, a tax collector who would rather not be recognised. They agree to walk together for a few days. Safety in numbers, even small numbers.","heroes":["h7"],"parties":[],"loc":"thornwall"},{"id":"e138","day":9,"season":1,"sday":9,"kind":"pet","imp":3,"text":"Mark slips Pickles a scrap from supper, and Pickles will now follow Mark to the ends of the realm. Ryan has noticed.","heroes":["h3","h14"],"parties":[],"loc":"kingsroad"},{"id":"e139","day":9,"season":1,"sday":9,"kind":"pet","imp":2,"text":"Pepper picks Katie out of the whole room at the camp and won't be argued with. Allie sighs and moves seats.","heroes":["h4","h16"],"parties":[],"loc":"kingsroad"},{"id":"e140","day":9,"season":1,"sday":9,"kind":"dream","imp":2,"text":"Griffin still means to make a fortune (2,000 silver earned). 10 silver down; 2,000 is the mark.","heroes":["h5"],"parties":[]}],"10":[{"id":"e144","day":10,"season":1,"sday":10,"kind":"evolve","imp":4,"text":"Matt the Warrior becomes an Armorer! A career heavy on crafting will do that: he hits things with things he made (mostly the other way round). First new trick: Hammer Down, and the guild sends over a Nasal Helm and a Smith's Hammer to go with it.","heroes":["h15"],"parties":[],"cls_to":"armorer"},{"id":"e145","day":10,"season":1,"sday":10,"kind":"fight","imp":2,"text":"Matt sees off a Kobold and a Cave Troll on floor 3 of the Collapsed Mine. Loot: 3 ore, 1 troll hide.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e146","day":10,"season":1,"sday":10,"kind":"fight","imp":2,"text":"The Green Hammers make short work of 2 Cliff Crabs and a Siren in the Salt Cliffs. Loot: 1 gem, 4 chitin, 4 fish.","heroes":["h1","h12"],"parties":["p5"],"loc":"saltcliffs"},{"id":"e147","day":10,"season":1,"sday":10,"kind":"night","imp":2,"text":"Harry tells a ghost story by the fire in the Salt Cliffs. Jeff laughs at it, then moves his bedroll closer to the others.","heroes":["h1","h12"],"parties":["p5"],"loc":"saltcliffs"},{"id":"e148","day":10,"season":1,"sday":10,"kind":"contract","imp":2,"text":"A quiet escort: bolts of cloth, Carrbridge to Hollowood, 41 each. The merchant tips extra for the conversation.","heroes":["h7"],"parties":[],"loc":"hollowood"},{"id":"e152","day":10,"season":1,"sday":10,"kind":"fight","imp":2,"text":"The Black Pack defeats 2 Bandit Captains, a Bandit and a Bandit Archer on the King's Road. Loot: 18 stolen goods, 1 ration, 1 gem.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"kingsroad"},{"id":"e153","day":10,"season":1,"sday":10,"kind":"song","imp":3,"text":"A bard at The Drowned Gull tries out \"The Ballad of Matt\" on a quiet night. It's about the day Matt became an Armorer, and it isn't quiet for long.","heroes":["h15"],"parties":[],"loc":"saltmarrow"},{"id":"e156","day":10,"season":1,"sday":10,"kind":"talent","imp":2,"text":"Keenan answers an old farmer's riddle at a gate and is let through the orchard for free, pockets full.","heroes":["h9"],"parties":["p2"],"loc":"kingsroad"},{"id":"e157","day":10,"season":1,"sday":10,"kind":"talent","imp":2,"text":"Amanda makes Troy stop walking on a twisted ankle. Troy complains, sits down, and is better by morning.","heroes":["h17","h8"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e158","day":10,"season":1,"sday":10,"kind":"argument","imp":3,"text":"The Green Hammers spend the evening listening to Jeff and Harry argue about whose turn it was to keep watch.","heroes":["h12","h1"],"parties":["p5"]},{"id":"e159","day":10,"season":1,"sday":10,"kind":"dream","imp":2,"text":"Late at night Allie counts it up again: to master the craft and reach level 18. Level 6, with 18 still a long climb off.","heroes":["h4"],"parties":[]},{"id":"e161","day":10,"season":1,"sday":10,"kind":"aside","imp":3,"text":"On the King's Road, Olivia sits up alone by the fire long after the others are asleep.","heroes":["h10"],"parties":[],"loc":"kingsroad"},{"id":"e162","day":10,"season":1,"sday":10,"kind":"aside","imp":3,"text":"Cade wakes before dawn from a dream about beasts and sits up until the light comes.","heroes":["h13"],"parties":[],"loc":"kingsroad"},{"id":"e163","day":10,"season":1,"sday":10,"kind":"aside","imp":3,"text":"Troy shares his supper with Maple the dog. Half of it. Fine, most of it.","heroes":["h8"],"parties":[],"loc":"goblin_camp"},{"id":"e164","day":10,"season":1,"sday":10,"kind":"mount","imp":3,"text":"A grey horse wanders out of the long grass beside the King's Road at dusk, looks the whole Black Pack over, and walks straight to Olivia. He eats the apple out of her hand, then her second apple, then lies down beside her bedroll as if it had always been the plan. Olivia names him Lord Guster. By morning they are best friends, and Clementine the cat has agreed to tolerate him.","heroes":["h10"],"parties":["p1"],"loc":"kingsroad"}],"11":[{"id":"e165","day":11,"season":1,"sday":11,"kind":"contract","imp":2,"text":"The guild clerks finally square their ledgers: an escort now counts as experience as well as silver, and Ryan, Olivia, Mark, Harry, Jeff and Corrine are credited for the roads already walked.","heroes":["h3","h10","h14","h1","h12","h7"],"parties":[]},{"id":"e167","day":11,"season":1,"sday":11,"kind":"legend","imp":4,"text":"Brother Toad, Keeper of the Long Road, gives Troy two potions in Goblin Camp and a look that says they'll need them.","heroes":["h8"],"parties":[],"loc":"goblin_camp","legend":"Brother Toad"},{"id":"e168","day":11,"season":1,"sday":11,"kind":"keystone","imp":2,"text":"The door is barely open and Matt is already through it, swinging. First Into the Breach: his first blows of every fight land extra hard.","heroes":["h15"],"parties":[],"ks":"First Into the Breach"},{"id":"e169","day":11,"season":1,"sday":11,"kind":"boss","imp":5,"text":"Matt slays the Silk Matriarch at the bottom of the Collapsed Mine. Loot: 11 chitin.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e170","day":11,"season":1,"sday":11,"kind":"treasure","imp":2,"text":"Under The Silk Matriarch's nest in the Collapsed Mine: 68 silver nobody else will ever claim.","heroes":["h15"],"parties":[],"loc":"collapsed_mine"},{"id":"e171","day":11,"season":1,"sday":11,"kind":"fight","imp":2,"text":"The Royal Shadows dispatch 3 Bandit Archers and a Bandit Captain on the King's Road. Loot: 4 stolen goods, 1 gem.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"kingsroad"},{"id":"e174","day":11,"season":1,"sday":11,"kind":"cooking","imp":2,"text":"The special at The Drowned Gull this week is Spider Crisps. Harry orders it twice and sends compliments to Captain Brine (retired).","heroes":["h1"],"parties":[],"loc":"saltmarrow"},{"id":"e180","day":11,"season":1,"sday":11,"kind":"fight","imp":3,"text":"First blood for Amanda and Griffin: Tidal Riders handle 4 Goblins and a Giant Rat on floor 1 of Goblin Camp. Whenever it looked bad, Amanda was already there. Loot: 5 goblin ears.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e181","day":11,"season":1,"sday":11,"kind":"contract","imp":3,"text":"Tidal Riders bring a sealed ledger up from floor 1 of Goblin Camp. Somebody in Ironhaven cries. 30 silver each.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e183","day":11,"season":1,"sday":11,"kind":"talent","imp":2,"text":"Jeff sells a haunch of venison to a Saltmarrow innkeeper, who asks for another by the end of the week.","heroes":["h12"],"parties":["p5"],"loc":"saltmarrow"},{"id":"e185","day":11,"season":1,"sday":11,"kind":"campfire","imp":2,"text":"Katie carves Allie's initials into the campfire log. Allie carves a rude drawing next to them. Friendship.","heroes":["h16","h4"],"parties":["p3"],"loc":"kingsroad"},{"id":"e186","day":11,"season":1,"sday":11,"kind":"argument","imp":4,"text":"Enough is enough: Harry tells Jeff exactly what Harry has been thinking for days. It's the third time this argument has come round. Nobody sleeps.","heroes":["h12","h1"],"parties":["p5"]},{"id":"e187","day":11,"season":1,"sday":11,"kind":"dream","imp":2,"text":"Some nights Ryan says it like a prayer: to own two named relics. The count stands at 0 of 2 named relics.","heroes":["h3"],"parties":[]},{"id":"e188","day":11,"season":1,"sday":11,"kind":"dream","imp":2,"text":"Amanda won't stop talking about it, and nobody minds much: to set foot in seven of the realm's towns. 2 of 7 towns, and counting.","heroes":["h17"],"parties":[]},{"id":"e189","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Black Pack sets their sights for the season: to find a relic of the old world. \"Somewhere out there is something nobody's touched in a thousand years,\" says Mark. \"We're going to be very careful with it.\"","heroes":["h14","h3","h10"],"parties":["p1"]},{"id":"e190","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Royal Shadows' plan for the season, as told to the barkeep: to bring down The Mimic King in Cragtooth Warren. \"If the treasure bites, we hit the treasure,\" says Andrew.","heroes":["h9","h13","h11"],"parties":["p2"]},{"id":"e191","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"The Pack of Carrbridge sets their sights for the season: to sit beneath the Mother Oak in Hollowood. \"Just sit,\" says Katie. \"Under a tree. With snacks. I've earned it.\"","heroes":["h4","h16"],"parties":["p3"]},{"id":"e192","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, Tidal Riders settle on a goal: to see the world, 6 different places before the season ends. \"Six is a lot of places,\" says Troy. \"Are we sure about six?\"","heroes":["h17","h8","h5"],"parties":["p4"]},{"id":"e193","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Green Hammers settle on a goal: to earn 650 silver between them before the season ends. \"Six hundred and fifty. Then we'll see,\" says Harry.","heroes":["h1","h12"],"parties":["p5"]},{"id":"e194","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"Corrine's plan for the season: to see the great forges in Ironhaven. \"I'll get there,\" she says. \"One thing first.\"","heroes":["h7"],"parties":[]},{"id":"e195","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"Matt has decided what this season is for: to earn 300 silver before the season ends. \"Hammers don't pay for themselves,\" he says.","heroes":["h15"],"parties":[]},{"id":"e196","day":11,"season":1,"sday":11,"kind":"goal","imp":2,"text":"Morgan has decided what this season is for: to earn 100 silver before the season ends. \"Start small,\" she says. \"Then don't stop.\"","heroes":["h18"],"parties":[]},{"id":"e199","day":11,"season":1,"sday":11,"kind":"aside","imp":3,"text":"Joshua shares his supper with Boomer the dog. Half of it. Fine, most of it. \"Nobody left behind. That's what counts,\" says Joshua.","heroes":["h11"],"parties":[],"loc":"kingsroad"},{"id":"e200","day":11,"season":1,"sday":11,"kind":"big_move","imp":4,"text":"Matt slays the Silk Matriarch at the bottom of the Collapsed Mine. On the table: Matt +72 renown (holds 1st).","heroes":["h15"],"parties":[],"cause":"e169"}],"12":[{"id":"e201","day":12,"season":1,"sday":12,"kind":"faction","imp":2,"text":"A Dawn patrol shares its fire with Olivia in Ironhaven and leaves a blessing and a pamphlet.","heroes":["h10"],"parties":[],"loc":"ironhaven"},{"id":"e205","day":12,"season":1,"sday":12,"kind":"treasure","imp":3,"text":"First treasure for Griffin, Amanda and Troy: Griffin kicks over a rotten crate on floor 1 of Goblin Camp. Out rolls 43 silver and a gem.","heroes":["h5","h17","h8"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e211","day":12,"season":1,"sday":12,"kind":"bodies","imp":2,"text":"Morgan drags the bandit's body out by the ankles, humming. Nobody is around to object.","heroes":["h18"],"parties":[],"loc":"greenwood"},{"id":"e212","day":12,"season":1,"sday":12,"kind":"ambush","imp":3,"text":"First blood for Morgan: Morgan sees off a Bandit on the road to the Greenwood. Loot: 3 rations.","heroes":["h18"],"parties":[],"loc":"greenwood"},{"id":"e214","day":12,"season":1,"sday":12,"kind":"contract","imp":2,"text":"The Black Pack agrees to fetch the mayor's spectacles from floor 2 of Cragtooth Warren. The family is very insistent.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"ironhaven"},{"id":"e216","day":12,"season":1,"sday":12,"kind":"boss_race","imp":3,"text":"A race for The Mimic King: The Black Pack and The Green Hammers are all bound for Cragtooth Warren. Only one of them gets the kill.","heroes":["h14","h3","h10","h1","h12"],"parties":["p1","p5"],"loc":"cragtooth_warren"},{"id":"e218","day":12,"season":1,"sday":12,"kind":"companion","imp":2,"text":"Osk goes one way at a milestone and Corrine the other. There are worse ways to spend a few days than in that company.","heroes":["h7"],"parties":[],"loc":"wolf_den"},{"id":"e219","day":12,"season":1,"sday":12,"kind":"gift","imp":3,"text":"Mark opens his pack and finds an Academy Ivory Chess set inside, wrapped in clean linen. He didn't buy it. Nobody owns up to it. Whoever it was must think a great deal of him.","heroes":["h14"],"parties":[],"loc":"cragtooth_warren"},{"id":"e220","day":12,"season":1,"sday":12,"kind":"gift","imp":2,"text":"Jeff picks up a set of Saltmarrow Shell Dice on the quay, pearl-white and loud on any table.","heroes":["h12"],"parties":[],"loc":"saltmarrow"},{"id":"e221","day":12,"season":1,"sday":12,"kind":"gift","imp":2,"text":"Ryan buys a Ledger-Ruled Deck from the Ironhaven guild printers. Even the aces look audited.","heroes":["h3"],"parties":[],"loc":"cragtooth_warren"},{"id":"e223","day":12,"season":1,"sday":12,"kind":"campfire","imp":2,"text":"Troy and Griffin walk point together all afternoon and say about nine words. Good words.","heroes":["h8","h5"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e224","day":12,"season":1,"sday":12,"kind":"dream","imp":2,"text":"Every road leads the same way for Andrew: to master the craft and reach level 18. Level 7 of 18.","heroes":["h2"],"parties":[]},{"id":"e225","day":12,"season":1,"sday":12,"kind":"dream","imp":2,"text":"Katie works it out on the back of a map, again: to set foot in seven of the realm's towns. 1 of 7 towns so far.","heroes":["h16"],"parties":[]}],"13":[{"id":"e230","day":13,"season":1,"sday":13,"kind":"fight","imp":2,"text":"The Black Pack beats 2 Goblin Archers, 2 Giant Bats and a Kobold on floor 1 of Cragtooth Warren. Olivia was wherever the trouble was, every time. Loot: 6 goblin ears, 1 fang.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e231","day":13,"season":1,"sday":13,"kind":"fight","imp":2,"text":"The Pack of Carrbridge outlasts a Bandit Captain, a Bandit and a Wolf on the King's Road. Nobody invited the wolves. They came anyway, drawn by the noise, and made it everyone's problem. Katie's Cleave did the damage (3 times). Loot: 5 stolen goods, 2 rations, 2 fangs & claws.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e232","day":13,"season":1,"sday":13,"kind":"cooking","imp":2,"text":"Amanda cooks Archer's Hotpot in Goblin Camp. Griffin has seconds and now hiccups bubbles.","heroes":["h17","h8","h5"],"parties":[],"loc":"goblin_camp"},{"id":"e234","day":13,"season":1,"sday":13,"kind":"treasure","imp":3,"text":"First treasure for Corrine: Mapping floor 1 of the Wolf Den, Corrine finds a narrow crawlway that opens into a dry cavern. Inside: 19 silver.","heroes":["h7"],"parties":[],"loc":"wolf_den"},{"id":"e235","day":13,"season":1,"sday":13,"kind":"ambush","imp":3,"text":"The Royal Shadows handle 2 Bandit Archers, a Bandit Captain and a Bandit on the road to Cragtooth Warren. Whenever it looked bad, Andrew was already there. Joshua picked the biggest one and did not regret it. \"We did right today,\" says Joshua. Loot: 11 stolen goods, 4 rations.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"kingsroad"},{"id":"e236","day":13,"season":1,"sday":13,"kind":"talent","imp":2,"text":"Andrew does an owl so well that a real owl lands on the tent. Joshua is speechless.","heroes":["h2","h11"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e238","day":13,"season":1,"sday":13,"kind":"bounty","imp":2,"text":"Matt dumps a sack of trophies on the guild counter in Veldrock and walks out 73 silver richer.","heroes":["h15"],"parties":[],"loc":"veldrock"},{"id":"e241","day":13,"season":1,"sday":13,"kind":"night_game","imp":3,"text":"A rivalry is born at camp on the King's Road: Katie beats Allie at dice, and Allie wants a rematch already.","heroes":["h16","h4"],"parties":[],"loc":"kingsroad"},{"id":"e242","day":13,"season":1,"sday":13,"kind":"night_game","imp":2,"text":"First game, first grudge: Jeff takes Harry at dice at camp by the road to Carrbridge, and the record between them begins.","heroes":["h12","h1"],"parties":[],"loc":"saltmarrow"},{"id":"e243","day":13,"season":1,"sday":13,"kind":"dream","imp":2,"text":"Harry hasn't given up on it: to slay the dragon of Emberdeep. The road is long; the dream is longer.","heroes":["h1"],"parties":[]},{"id":"e244","day":13,"season":1,"sday":13,"kind":"dream","imp":2,"text":"Matt hasn't forgotten the dream: to own two named relics. 0 named relics down; 2 is the mark.","heroes":["h15"],"parties":[]}],"14":[{"id":"e246","day":14,"season":1,"sday":13,"kind":"retrain","imp":3,"text":"Harry sells the dusty lexicon and the brass lens that hums near magic, and spends the money on a songbook. The humming has not stopped since.","heroes":["h1"],"parties":[],"loc":"saltmarrow"},{"id":"e247","day":14,"season":1,"sday":13,"kind":"retrain","imp":2,"text":"Mark stops squinting at enchanted trinkets and spends the mornings at the shrine instead. The quiet suits Mark.","heroes":["h14"],"parties":[],"loc":"cragtooth_warren"},{"id":"e248","day":14,"season":1,"sday":13,"kind":"retrain","imp":2,"text":"Olivia gives up the old spark tricks for tricks of light and shadow. Nobody can quite say where Olivia is standing.","heroes":["h10"],"parties":[],"loc":"cragtooth_warren"},{"id":"e249","day":14,"season":1,"sday":13,"kind":"retrain","imp":2,"text":"Keenan stops counting out magic missiles and lets the fire do the talking. The spellbook smells of smoke now.","heroes":["h9"],"parties":[],"loc":"cragtooth_warren"},{"id":"e250","day":14,"season":1,"sday":13,"kind":"retrain","imp":2,"text":"Griffin's speeches have found a god. The drills are blessings now, delivered loudly.","heroes":["h5"],"parties":[],"loc":"goblin_camp"},{"id":"e252","day":14,"season":1,"sday":14,"kind":"fame","imp":3,"text":"The Gilded Flagon has a new portrait of Olivia on its wall: flattering in some places, wrong in others.","heroes":["h10"],"parties":[],"loc":"ironhaven"},{"id":"e255","day":14,"season":1,"sday":14,"kind":"town","imp":3,"text":"Fire at the bakery in Carrbridge! Allie joins the bucket line. They come out smelling of smoke and burnt bread.","heroes":["h4"],"parties":[],"loc":"carrbridge"},{"id":"e256","day":14,"season":1,"sday":14,"kind":"trait","imp":3,"text":"Helping kill Gruk the Warchief, a Goblin Shaman and a Goblin has changed Amanda. She is bolder now (boldness: cautious → steady).","heroes":["h17"],"parties":[]},{"id":"e257","day":14,"season":1,"sday":14,"kind":"relic_found","imp":3,"text":"First relic for Amanda: something small and old slips into her pocket in Goblin Camp. Nobody else sees it. Probably.","heroes":["h17"],"parties":[],"loc":"goblin_camp"},{"id":"e258","day":14,"season":1,"sday":14,"kind":"boss","imp":5,"text":"At the bottom of Goblin Camp, Tidal Riders slay Gruk the Warchief, a Goblin Shaman and a Goblin. Amanda found the weak spot first and kept hitting it; without Griffin's Battle Cry, this goes differently. Loot: 7 goblin ears, 6 trinkets, Gruk's own smoked ham.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e260","day":14,"season":1,"sday":14,"kind":"cooking","imp":3,"text":"From the spoils, Griffin cooks Gruk's Victory Ham in Goblin Camp. Nobody says a word until it's gone: the best thing Gruk ever owned, and they'll talk about it for years.","heroes":["h17","h8","h5"],"parties":[],"loc":"goblin_camp"},{"id":"e261","day":14,"season":1,"sday":14,"kind":"gear","imp":2,"text":"Matt walks out of Ulf Two-Fingers's shop with a Flanged Mace and a much lighter purse (155 silver).","heroes":["h15"],"parties":[],"loc":"veldrock"},{"id":"e262","day":14,"season":1,"sday":14,"kind":"ambush","imp":2,"text":"Matt makes short work of 2 Bandit Captains on the road to Frosthold. The last bandit captain bolts. Loot: 3 stolen goods.","heroes":["h15"],"parties":[],"loc":"kingsroad"},{"id":"e263","day":14,"season":1,"sday":14,"kind":"fight","imp":2,"text":"The Black Pack makes short work of 3 Goblin Archers and a Kobold on floor 1 of Cragtooth Warren. Loot: 6 goblin ears, 3 walking-caps, 1 trinket.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e264","day":14,"season":1,"sday":14,"kind":"town","imp":3,"text":"A stray dog follows Jeff around Carrbridge all day and refuses to leave. They name it Nugget, and it is a member of the league now.","heroes":["h12"],"parties":[],"loc":"carrbridge"},{"id":"e267","day":14,"season":1,"sday":14,"kind":"fight","imp":2,"text":"The Royal Shadows dispatch 2 Kobolds, 2 Giant Bats and a Goblin Archer on floor 1 of Cragtooth Warren. The last goblin archer bolts. Loot: 2 ore, 3 kobold firepeppers.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e269","day":14,"season":1,"sday":14,"kind":"evolve","imp":4,"text":"Keenan the Mage becomes a Pyromancer! A career heavy on fire will do that: Flame Jet and Firebolt led the way, and the first new trick is Fireball. Eyebrows: a memory.","heroes":["h9"],"parties":[],"cls_to":"pyromancer"},{"id":"e270","day":14,"season":1,"sday":14,"kind":"ambush","imp":3,"text":"In the middle of the night, The Royal Shadows make short work of 3 Kobolds at their camp in Cragtooth Warren. Cade kept a cool head while everyone else was shouting, and Andrew and Socks the dog found the way out together. Loot: 1 ore, 4 kobold firepeppers.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e271","day":14,"season":1,"sday":14,"kind":"song","imp":3,"text":"Somebody at The Watching Oak has written \"Where Keenan Walks\", and now Hollowood can't stop humming it: a song about the way down into Cragtooth Warren, with Keenan in it.","heroes":["h9"],"parties":[],"loc":"hollowood"},{"id":"e275","day":14,"season":1,"sday":14,"kind":"campfire","imp":2,"text":"Mark and Ryan sit on opposite sides of the campfire and end up, somehow, on the same side.","heroes":["h14","h3"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e277","day":14,"season":1,"sday":14,"kind":"bond","imp":2,"text":"Allie and Katie have become friends, the slow, honest kind that starts with sharing a fire.","heroes":["h4","h16"],"parties":[],"loc":"carrbridge","bond":"friends"},{"id":"e279","day":14,"season":1,"sday":14,"kind":"dream","imp":2,"text":"If you've shared a fire with Mark, you know the plan: to set foot in seven of the realm's towns. 2 towns down; 7 is the mark.","heroes":["h14"],"parties":[]},{"id":"e280","day":14,"season":1,"sday":14,"kind":"goal_progress","imp":2,"text":"Matt is getting close: earn 300 silver before the season ends (183 of 300 silver).","heroes":["h15"],"parties":[]},{"id":"e282","day":14,"season":1,"sday":14,"kind":"ledger","imp":2,"text":"The week's trade: 7 packs emptied onto counters for 375 silver. Biggest haul: Ryan, 105 silver in Ironhaven. Back up from the deep: Matt (5 days in the Collapsed Mine), Corrine (3 days in the Wolf Den).","heroes":["h3","h15","h7"],"parties":[]},{"id":"e283","day":14,"season":1,"sday":14,"kind":"big_move","imp":4,"text":"Tidal Riders slay Gruk the Warchief, a Goblin Shaman and a Goblin at the bottom of Goblin Camp, and the table shakes: Troy +55 renown (14th to 2nd), Griffin +53 (16th to 5th), Tidal Riders +104 party renown (3rd to 1st among the crews).","heroes":["h8","h5"],"parties":["p4"],"cause":"e258"}],"15":[{"id":"e285","day":15,"season":1,"sday":15,"kind":"fame","imp":3,"text":"Troy has a fan now: a baker from Thornwall who follows him around asking about the fighting.","heroes":["h8"],"parties":[],"loc":"thornwall"},{"id":"e287","day":15,"season":1,"sday":15,"kind":"legend","imp":4,"text":"In the Greenwood, Sable Vey, the Wandering Star, challenges Morgan to a friendly duel. Morgan lasts longer than most and learns more than expected.","heroes":["h18"],"parties":[],"loc":"greenwood","legend":"Sable Vey"},{"id":"e289","day":15,"season":1,"sday":15,"kind":"talent","imp":2,"text":"Amanda sits up with Troy through a fever, talking about nothing. By morning Troy is sitting up and asking for breakfast.","heroes":["h17","h8"],"parties":["p4"],"loc":"goblin_camp"},{"id":"e291","day":15,"season":1,"sday":15,"kind":"evolve","imp":4,"text":"Cade the Ranger becomes a Sharpshooter! A career heavy on precise strikes will do that, with Aimed Shot leading the way. Picks the eye, hits the eye. First new trick: Piercing Arrow, and the guild sends a Wide-Brimmed Hat to go with it.","heroes":["h13"],"parties":[],"cls_to":"sharpshooter"},{"id":"e292","day":15,"season":1,"sday":15,"kind":"evolve","imp":4,"text":"Joshua the Mage becomes an Arcanist! Magic Missile and Arcane Shield led the way on a career heavy on arcane study. Skipped the specialty, kept the whole library. First new trick: Arcane Torrent.","heroes":["h11"],"parties":[],"cls_to":"arcanist"},{"id":"e293","day":15,"season":1,"sday":15,"kind":"evolve","imp":4,"text":"Andrew the Warrior becomes a Berserker! Last Stand and Dirty Fighting led the way on a career heavy on fury. Shirt optional, restraint absent. First new trick: Berserk, plus a Horned Helm from the guild.","heroes":["h2"],"parties":[],"cls_to":"berserker"},{"id":"e294","day":15,"season":1,"sday":15,"kind":"fight","imp":2,"text":"The Royal Shadows defeat 2 Giant Bats, 2 Kobolds and a Goblin Archer on floor 1 of Cragtooth Warren. The last giant bat bolts. Loot: 2 goblin ears, 1 ore, 3 kobold firepeppers.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e296","day":15,"season":1,"sday":15,"kind":"reading","imp":2,"text":"Matt pays Grandmother Skaldi at a hut at the edge of the snowfield for a first reading and gets the Ten of Pentacles for the money. Grandmother Skaldi says it's a good card to start on, and doesn't say why.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e297","day":15,"season":1,"sday":15,"kind":"reading","imp":2,"text":"Sabine Venn lays out Harry's first spread at the toll-house parlour. \"The Ten of Swords upside down,\" Sabine Venn says, and lets it sit there.","heroes":["h1"],"parties":[],"loc":"carrbridge"},{"id":"e298","day":15,"season":1,"sday":15,"kind":"ambush","imp":2,"text":"The Green Hammers beat a Bandit Captain on the road to Ironhaven. Harry was wherever the trouble was, every time. Jeff pocketed something shiny when nobody was looking. \"Leave the heads,\" says Jeff. Loot: 7 stolen goods, 3 bandit sausages.","heroes":["h1","h12"],"parties":["p5"],"loc":"kingsroad"},{"id":"e301","day":15,"season":1,"sday":15,"kind":"song","imp":3,"text":"\"Nobody Told Cade\" turns up at The Gilded Flagon, author unknown, every verse about the way down into Cragtooth Warren with Cade in it. The landlord bans it twice and gives up.","heroes":["h13"],"parties":[],"loc":"ironhaven"},{"id":"e302","day":15,"season":1,"sday":15,"kind":"song","imp":3,"text":"On a quiet night at The Third Coat, a bard tries out \"Here Comes Joshua\", about the day Joshua went back for a friend on the King's Road. It isn't quiet for long.","heroes":["h11"],"parties":[],"loc":"frosthold"},{"id":"e303","day":15,"season":1,"sday":15,"kind":"song","imp":3,"text":"New at The Sagging Beam tonight: \"Ring the Bells for Andrew\", about the day Andrew went back for a friend on the King's Road. By the third verse the whole room knows the words.","heroes":["h2"],"parties":[],"loc":"thornwall"},{"id":"e305","day":15,"season":1,"sday":15,"kind":"music","imp":3,"text":"Mark sang a new song at the fire last night, \"Somebody Packed a Chess Set\": \"In my pack, wrapped clean, an ivory chess set / Someone thinks well of me, and won't say who\"","heroes":["h14"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e307","day":15,"season":1,"sday":15,"kind":"pet","imp":3,"text":"All evening, Pickles sits between Ryan and Olivia, facing Olivia, unblinking.","heroes":["h3","h10"],"parties":[],"loc":"cragtooth_warren"},{"id":"e309","day":15,"season":1,"sday":15,"kind":"dream","imp":2,"text":"Cade's dream hasn't changed: to have three true friends. The friendships are still forming.","heroes":["h13"],"parties":[]}],"16":[{"id":"e311","day":16,"season":1,"sday":16,"kind":"underdog","imp":3,"text":"Seventeenth of 17 and still swinging: on day 12 of season 1, Morgan saw off a Bandit on the road to the Greenwood. Don't count her out.","heroes":["h18"],"parties":[]},{"id":"e315","day":16,"season":1,"sday":16,"kind":"relic","imp":3,"text":"Sister Amberline holds Amanda's relic to the light, prays over it for an hour, and names it the Hearthstone Pendant (cheers the party). The fire burns warmer near it. Somebody starts singing, and nobody stops them.","heroes":["h17"],"parties":[],"loc":"thornwall"},{"id":"e319","day":16,"season":1,"sday":16,"kind":"cooking","imp":2,"text":"Old Hesk has written The Sergeant's Roast on the board at The Sagging Beam in letters a foot high: dish of the week. Amanda orders it before sitting down. It is carved at attention. (3 silver)","heroes":["h17"],"parties":[],"loc":"thornwall"},{"id":"e322","day":16,"season":1,"sday":16,"kind":"keystone","imp":2,"text":"'Ask Keenan anything. Then clear your afternoon,' says a librarian. Keenan is a Walking Library: old carvings and dusty inscriptions teach him a great deal.","heroes":["h9"],"parties":[],"ks":"Walking Library"},{"id":"e323","day":16,"season":1,"sday":16,"kind":"fight","imp":2,"text":"The Royal Shadows defeat 2 Cave Slimes, a Cave Troll and a Kobold Slinger on floor 2 of Cragtooth Warren. Joshua saved Arcane Shield for when it mattered. Loot: 4 slime jelly, 4 ore.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e326","day":16,"season":1,"sday":16,"kind":"pet","imp":2,"text":"Bear will not stop glaring at Amanda across The Sagging Beam. Griffin trusts the dog's judgement.","heroes":["h5","h17"],"parties":[],"loc":"thornwall"},{"id":"e328","day":16,"season":1,"sday":16,"kind":"bar_fight","imp":5,"text":"BAR FIGHT at The Sagging Beam! Griffin insists the last round was already paid for, and within a minute Morgan, Griffin and Troy are all in it. Troy goes through the window; Griffin goes out the door, bowing. Old Hesk bills Griffin 26 silver for the furniture and bans him for three nights.","heroes":["h18","h5","h8"],"parties":["p4"],"loc":"thornwall"},{"id":"e330","day":16,"season":1,"sday":16,"kind":"mood","imp":2,"text":"Joshua isn't sleeping. Someone notices the untouched bedroll three nights running.","heroes":["h11"],"parties":[],"loc":"cragtooth_warren"},{"id":"e331","day":16,"season":1,"sday":16,"kind":"song","imp":3,"text":"A travelling bard at The Sagging Beam has a new song, \"Lanterns for Morgan\", every verse about a tavern brawl in Thornwall. The chorus is already stuck in everyone's head.","heroes":["h18"],"parties":["p4"],"loc":"thornwall"},{"id":"e332","day":16,"season":1,"sday":16,"kind":"meet","imp":2,"text":"The Royal Shadows and The Green Hammers share a fire in Cragtooth Warren and trade news.","heroes":["h9","h13","h11","h2","h1","h12"],"parties":["p2","p5"],"loc":"cragtooth_warren"},{"id":"e333","day":16,"season":1,"sday":16,"kind":"talent","imp":2,"text":"Matt hears a twig snap and charges into the bushes. It's a deer. The deer is very surprised.","heroes":["h15"],"parties":[],"loc":"whitepeak"},{"id":"e334","day":16,"season":1,"sday":16,"kind":"talent","imp":2,"text":"Katie casts a line from every bridge on the route. At the fourth, a pike. Katie names it.","heroes":["h16"],"parties":["p3"],"loc":"thornwall"},{"id":"e336","day":16,"season":1,"sday":16,"kind":"ability","imp":2,"text":"Keenan stops in front of a carved wall in Cragtooth Warren and reads it like the morning paper. He comes away knowing who built the place, why, and three new words.","heroes":["h9"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e338","day":16,"season":1,"sday":16,"kind":"argument","imp":2,"text":"Jeff and Harry spend supper disagreeing about who lost the map, politely at first.","heroes":["h12","h1"],"parties":["p5"]},{"id":"e340","day":16,"season":1,"sday":16,"kind":"dream","imp":2,"text":"Over the last of the ale, Jeff says it out loud again: to be the most famous hero in the league.","heroes":["h12"],"parties":[]}],"17":[{"id":"e342","day":17,"season":1,"sday":17,"kind":"reading","imp":2,"text":"A first reading for Morgan at the toll-house parlour. Sabine Venn turns the Sun, raises an eyebrow, and asks if Morgan has been sleeping well.","heroes":["h18"],"parties":[],"loc":"carrbridge"},{"id":"e344","day":17,"season":1,"sday":17,"kind":"town_life","imp":2,"text":"The Hollowood crier, half-drunk on importance, reads out Allie's name among the notable citizens by mistake. The square cheers. Allie bows.","heroes":["h4"],"parties":[],"loc":"hollowood"},{"id":"e346","day":17,"season":1,"sday":17,"kind":"night","imp":2,"text":"Joshua follows strange lights away from the camp outside Cragtooth Warren and comes back at dawn with a trinket and no explanation.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e348","day":17,"season":1,"sday":17,"kind":"evolve","imp":4,"text":"Harry the Mage is a Bard now, on a career heavy with Busker and Songwriter. The guild sends a Feathered Cap, and his first new trick is Off-Key Note: morale, publicist and liability in one.","heroes":["h1"],"parties":[],"cls_to":"bard"},{"id":"e349","day":17,"season":1,"sday":17,"kind":"voice","imp":3,"text":"Something in Harry opened up with the new calling. He talks in verse now, half the time without noticing.","heroes":["h1"],"parties":[]},{"id":"e352","day":17,"season":1,"sday":17,"kind":"boss_race","imp":3,"text":"A race for Vessimir the Unburied is on: The Black Pack and Morgan are both bound for the Ashveil Crypts, and only one of them gets the kill.","heroes":["h14","h3","h10","h18"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e354","day":17,"season":1,"sday":17,"kind":"song","imp":3,"text":"\"Harry of the Long Road\" gets its first airing at The Drowned Gull, a song about the legend Harry met in Frosthold. Three encores and one thrown boot.","heroes":["h1"],"parties":[],"loc":"saltmarrow"},{"id":"e359","day":17,"season":1,"sday":17,"kind":"pet","imp":2,"text":"Maple and Bear become fast friends at the Greenwood. Their owners, Troy and Griffin, have no choice but to follow suit.","heroes":["h8","h5"],"parties":[],"loc":"greenwood"},{"id":"e361","day":17,"season":1,"sday":17,"kind":"dream","imp":2,"text":"Joshua brings it up again over supper: to have three true friends. 1 true friend so far.","heroes":["h11"],"parties":[]},{"id":"e362","day":17,"season":1,"sday":17,"kind":"goal_done","imp":4,"text":"PILGRIMAGE: The Pack of Carrbridge reaches Hollowood at last and sits beneath the Mother Oak; nobody says much, and everybody walks back lighter. \"It was Katie's idea,\" says Allie, \"and it was a good one.\"","heroes":["h4","h16"],"parties":["p3"],"loc":"hollowood"},{"id":"e364","day":17,"season":1,"sday":17,"kind":"hunters_gone","imp":3,"text":"The price on Matt's head lapses. Whoever was hunting Matt found Matt hard to pin down, and too well known to try it in town.","heroes":["h15"],"parties":[]},{"id":"e365","day":17,"season":1,"sday":17,"kind":"hunters_gone","imp":2,"text":"Nobody collects on Andrew's head this time. The wanted sketches go soft in the rain.","heroes":["h2"],"parties":[]}],"18":[{"id":"e366","day":18,"season":1,"sday":18,"kind":"weather","imp":2,"text":"It rains on the centre all day. Jeff insists it is good for the crops, to no one in particular.","heroes":["h12"],"parties":[],"loc":"ironhaven"},{"id":"e367","day":18,"season":1,"sday":18,"kind":"omen","imp":3,"text":"Omens are stirring: a shepherd swears a hill moved, and nobody laughs as much as they would have last year. Matt saw it first.","heroes":["h15"],"parties":[]},{"id":"e370","day":18,"season":1,"sday":18,"kind":"fight","imp":2,"text":"Matt dispatches a Frost Wolf and an Ice Wraith on floor 1 of Frostspire. The frost wolf went down to Matt's Power Strike. Loot: 5 pelts.","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e371","day":18,"season":1,"sday":18,"kind":"treasure","imp":3,"text":"Floor 1 of Frostspire: a dead adventurer won't be needing 20 gold pieces, 6 silver, a gem and a jar of wraith-frost any more. Matt takes it, with thanks.","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e372","day":18,"season":1,"sday":18,"kind":"ambush","imp":2,"text":"The Royal Shadows cut down 4 Wolves on the road to Ironhaven. The last wolf bolts. The wolf had been trouble right up until Keenan's Frost Shard. Andrew found the weak spot first and kept hitting it. Keenan and Mango the lizard found the way out together. Loot: 5 fangs & claws, 2 pelts.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"kingsroad"},{"id":"e374","day":18,"season":1,"sday":18,"kind":"party_life","imp":3,"text":"On the road, Amanda rides ahead, rides back, then rides ahead again. Troy and Griffin are not amused.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"greenwood"},{"id":"e375","day":18,"season":1,"sday":18,"kind":"evolve","imp":4,"text":"Aimed Shot did the talking: Jeff the Ranger is now a Sharpshooter, with Piercing Arrow as a first new trick and a Wide-Brimmed Hat from the guild. Picks the eye. Hits the eye.","heroes":["h12"],"parties":[],"cls_to":"sharpshooter"},{"id":"e376","day":18,"season":1,"sday":18,"kind":"fight","imp":2,"text":"The Green Hammers cut down 2 Cave Slimes on floor 2 of Cragtooth Warren. Somewhere around Jeff's Thorn Whip, the other side stopped believing. Jeff landed 2 crushing blows, mostly with Aimed Shot. Loot: 1 gem.","heroes":["h1","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e377","day":18,"season":1,"sday":18,"kind":"talent","imp":2,"text":"Jeff says a quiet grace over the fire. Harry bows too, a beat late. The words of Devout, half under their breath.","heroes":["h12","h1"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e378","day":18,"season":1,"sday":18,"kind":"boss_race","imp":2,"text":"The Black Pack drops out of the race for The Mimic King. That leaves The Green Hammers in it.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"cragtooth_warren"},{"id":"e379","day":18,"season":1,"sday":18,"kind":"boss_race","imp":2,"text":"The race for The Mimic King is one crew lighter: The Royal Shadows turned for other work. That leaves The Green Hammers.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e380","day":18,"season":1,"sday":18,"kind":"song","imp":2,"text":"At The Gilded Flagon, Cade sits at the back through \"Nobody Told Cade\" and tells nobody who it's about. Everybody knows.","heroes":["h13"],"parties":[],"loc":"ironhaven"},{"id":"e381","day":18,"season":1,"sday":18,"kind":"song","imp":2,"text":"Joshua hums along to \"Here Comes Joshua\" at The Gilded Flagon, gets two verses wrong, and corrects the bard anyway.","heroes":["h11"],"parties":[],"loc":"ironhaven"},{"id":"e382","day":18,"season":1,"sday":18,"kind":"song","imp":3,"text":"At The Drowned Gull, a bard with a cracked lute sings \"Old Cragtooth Warren, Young Jeff\", all about the way down into Cragtooth Warren with Jeff on the stair. The lute is the only thing in the room that doesn't join in.","heroes":["h12"],"parties":[],"loc":"saltmarrow"},{"id":"e384","day":18,"season":1,"sday":18,"kind":"fishing","imp":2,"text":"Katie lands a Golden Carp by a stream on the road to Thornwall, the first the league has ever seen. The anglers will want to hear about it.","heroes":["h16"],"parties":[],"loc":"thornwall"},{"id":"e386","day":18,"season":1,"sday":18,"kind":"campfire","imp":2,"text":"Joshua and Andrew have been in The Royal Shadows together for a fortnight. They've stopped saying \"please\" and started saying \"pass it\".","heroes":["h11","h2"],"parties":["p2"],"loc":"ironhaven"},{"id":"e388","day":18,"season":1,"sday":18,"kind":"goal_progress","imp":2,"text":"Tidal Riders are getting close: see the world: 6 different places before the season ends (4 of 6 places).","heroes":["h17","h8","h5"],"parties":["p4"]},{"id":"e389","day":18,"season":1,"sday":18,"kind":"goal_done","imp":4,"text":"Matt can cross it off: 300 silver earned before the season ends, +919 XP and level 15. Drinks are on him. \"Don't get used to it,\" Matt says. \"I won't.\"","heroes":["h15"],"parties":[]},{"id":"e391","day":18,"season":1,"sday":18,"kind":"big_move","imp":4,"text":"Another goal ticked off for Matt: 300 silver earned before the season ends. On the table: Matt +61 renown, and he holds 1st.","heroes":["h15"],"parties":[],"cause":"e389"}],"19":[{"id":"e392","day":19,"season":1,"sday":18,"kind":"rework","imp":3,"text":"Word from every guild hall: the old tunnels have shifted, every lair has new rooms and new tenants, and every map drawn before today is waste paper. The guilds hand every hero a torch and buy back the old maps from the fourteen who held one.","heroes":["h1","h2","h3","h5","h7","h8","h9","h10","h11","h12","h13","h14","h15","h17"],"parties":[]},{"id":"e393","day":19,"season":1,"sday":19,"kind":"weather","imp":2,"text":"The north wakes up white. Matt's boots were not made for this.","heroes":["h15"],"parties":[],"loc":"frosthold"},{"id":"e394","day":19,"season":1,"sday":19,"kind":"faction","imp":2,"text":"A Dawn patrol shares its fire with Joshua in Ironhaven and leaves a blessing and a pamphlet.","heroes":["h11"],"parties":[],"loc":"ironhaven"},{"id":"e395","day":19,"season":1,"sday":19,"kind":"ambush","imp":2,"text":"The Pack of Carrbridge gets the better of 3 Wolves on the road to Thornwall. The wolf took Katie's Cleave full on and was never the same after. Allie's Frost Shard did the damage (2 times). Loot: 2 pelts, a wolf haunch.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e396","day":19,"season":1,"sday":19,"kind":"road","imp":3,"text":"Supper on the road: Marigold sets up the pot, Katie is given the spoon to hold, and the smell makes the miles ahead seem short.","heroes":["h16","h4"],"parties":["p3"]},{"id":"e397","day":19,"season":1,"sday":19,"kind":"road","imp":3,"text":"Ines has drawn a road that does not exist, and is thrilled by it. Ryan, gently, points out the hedge where it should be.","heroes":["h3","h10","h14"],"parties":["p1"]},{"id":"e399","day":19,"season":1,"sday":19,"kind":"map_bought","imp":2,"text":"The Royal Shadows buy a map of Cragtooth Warren in Ironhaven for 30 silver. The place is untouched (0%).","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"ironhaven"},{"id":"e400","day":19,"season":1,"sday":19,"kind":"road","imp":3,"text":"At Gallows Cross the Lantern Lady asks, 'Which road do you mean to take?' A card appears from nowhere and she turns it face up for Corrine to read.","heroes":["h7"],"parties":[]},{"id":"e401","day":19,"season":1,"sday":19,"kind":"wild_room","imp":3,"text":"Jeff cleaned out the knucklebones circle in Cragtooth Warren, and the kobolds are now checking their bones for weights.","heroes":["h1","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e404","day":19,"season":1,"sday":19,"kind":"fight","imp":2,"text":"It's 4 Wolves against Tidal Riders in the bone yard on floor 1 of the Wolf Den, and it isn't close. The last wolf turns tail. Griffin's Battle Cry had everyone hitting harder. Troy kept them off everyone with Phantasm. Loot: 2 pelts, 4 fangs & claws, a wolf haunch. Amanda, who has been afraid of beasts since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e405","day":19,"season":1,"sday":19,"kind":"trap","imp":2,"text":"Griffin springs an old hunter's deadfall in the root curtain on floor 1 of the Wolf Den (deep cut).","heroes":["h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e406","day":19,"season":1,"sday":19,"kind":"trap","imp":3,"text":"Mind the roots: Griffin springs an old hunter's deadfall in the root curtain on floor 1 of the Wolf Den (concussion).","heroes":["h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e411","day":19,"season":1,"sday":19,"kind":"bond","imp":3,"text":"Olivia and Morgan have known each other a day and already have a grudge with a name. Rivals.","heroes":["h10","h18"],"parties":[],"bond":"rivals"},{"id":"e412","day":19,"season":1,"sday":19,"kind":"journey","imp":2,"text":"The Black Pack and Morgan fall in together on the road to Ashfen and spend the miles arguing about Ryan's terrible singing.","heroes":["h14","h3","h10","h18"],"parties":["p1"]},{"id":"e413","day":19,"season":1,"sday":19,"kind":"music","imp":3,"text":"\"The Feathered Cap\", a new song by Harry, about the week they just had: \"The guild has sent a feathered cap, / and I will sing it right.\"","heroes":["h1"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e415","day":19,"season":1,"sday":19,"kind":"cooking","imp":2,"text":"Supper in the Wolf Den is some Wolf Stew. Griffin pretends not to watch everyone's faces. It is wolf, which nobody mentions to the horses.","heroes":["h17","h8","h5"],"parties":[],"loc":"wolf_den"},{"id":"e416","day":19,"season":1,"sday":19,"kind":"campfire","imp":2,"text":"Griffin shows Amanda a scar and Amanda shows one back. They compare, warily.","heroes":["h5","h17"],"parties":["p4"],"loc":"wolf_den"},{"id":"e417","day":19,"season":1,"sday":19,"kind":"dream","imp":2,"text":"Keenan keeps the tally inside a boot, where nobody else will read it: to master the craft and reach level 18 this season. Level 10 now; 18 is the mark.","heroes":["h9"],"parties":[]},{"id":"e418","day":19,"season":1,"sday":19,"kind":"goal_done","imp":4,"text":"PILGRIMAGE: Corrine makes it to Ironhaven to see the great forges, and something old gets set down there and left. +960 XP, and Corrine reaches level 9. \"I came a long way to put it down,\" says Corrine. \"I think it's lighter here.\"","heroes":["h7"],"parties":[],"loc":"ironhaven"},{"id":"e419","day":19,"season":1,"sday":19,"kind":"evolve","imp":4,"text":"Corrine the Ranger becomes a Pathfinder! A career heavy on the open road and the wilds will do that; Trailblazer and Ambush led the way. (Has never once been lost. Claims to have never once been lost.) First new trick: Lay of the Land.","heroes":["h7"],"parties":[],"cls_to":"pathfinder"}],"20":[{"id":"e421","day":20,"season":1,"sday":19,"kind":"mount","imp":2,"text":"Word of Griffin's Drover reaches the riders' guild, which won't have anyone who knows the saddle on foot: Griffin is lent a riding horse called Turnip, on the understanding it comes back one day.","heroes":["h5"],"parties":[],"loc":"wolf_den"},{"id":"e423","day":20,"season":1,"sday":20,"kind":"road","imp":3,"text":"On the road, Brother Aldo tells Morgan he has been to forty shrines this year, then names every one of them. Slowly.","heroes":["h18"],"parties":[]},{"id":"e425","day":20,"season":1,"sday":20,"kind":"road","imp":2,"text":"Corrine reports a fallen sign on the road to Thornwall to Sergeant Pellam at the Mile-Warden's hut. The sergeant thanks her and promises it will be fixed by the weekend, a promise Corrine chooses to believe.","heroes":["h7"],"parties":[]},{"id":"e426","day":20,"season":1,"sday":20,"kind":"fishing","imp":2,"text":"The books show no Perch until today, when Corrine lands one at the Thornwall millpond.","heroes":["h7"],"parties":[],"loc":"thornwall"},{"id":"e432","day":20,"season":1,"sday":20,"kind":"night","imp":2,"text":"Something sings in the dark on the King's Road. Katie goes to look and comes back with a trinket and a very quiet manner.","heroes":["h4","h16"],"parties":["p3"],"loc":"kingsroad"},{"id":"e434","day":20,"season":1,"sday":20,"kind":"keystone","imp":2,"text":"'Aim where Cade's second arrow is sticking out. That's the whole trick,' says a partymate. Follow My Arrow: after a critical hit, Cade looses again and shows the party where to strike.","heroes":["h13"],"parties":[],"ks":"Follow My Arrow"},{"id":"e435","day":20,"season":1,"sday":20,"kind":"fight","imp":2,"text":"In the bat roost on the first floor of Cragtooth Warren, the Royal Shadows square up to 3 Giant Bats and a Kobold and carry the day. Three giant bats went down together, and they have Cade's Volley to thank. Loot: 2 silver each, a pair of bat wings. Andrew, who has been afraid of the dark since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e436","day":20,"season":1,"sday":20,"kind":"wild_room","imp":3,"text":"Down in Cragtooth Warren, The Royal Shadows walk straight past a chest labelled DEFINITELY NOT A MIMIC. The mimic is said to be disappointed.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e437","day":20,"season":1,"sday":20,"kind":"gear","imp":3,"text":"Behind a walled-up room beside the chest on the plinth, on the first floor of Cragtooth Warren, Joshua finds a Lucky Runed Staff and puts it on: +2 crit, and a step up from anything Joshua could buy.","heroes":["h11"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e439","day":20,"season":1,"sday":20,"kind":"spark","imp":3,"text":"The tavern boards now list Andrew above Jeff. Jeff is taking it personally.","heroes":["h2","h12"],"parties":[]},{"id":"e440","day":20,"season":1,"sday":20,"kind":"bond","imp":3,"text":"It's official: The Royal Shadows and The Green Hammers are rivals, and it started with Andrew and Jeff.","heroes":["h2","h12"],"parties":["p2","p5"],"bond":"rivals"},{"id":"e441","day":20,"season":1,"sday":20,"kind":"song","imp":2,"text":"Four taverns, four versions of \"Lanterns for Morgan\". The one in Carrbridge swears it's the true one.","heroes":["h18"],"parties":[],"loc":"carrbridge"},{"id":"e442","day":20,"season":1,"sday":20,"kind":"meet","imp":2,"text":"The Black Pack and Morgan camp within sight of each other in the Ashveil Crypts and spend the night pretending not to watch.","heroes":["h14","h3","h10","h18"],"parties":["p1"],"loc":"ashveil_crypts"},{"id":"e443","day":20,"season":1,"sday":20,"kind":"meet","imp":2,"text":"The Green Hammers and The Royal Shadows end up at the same fire in Cragtooth Warren. Nobody speaks. Everybody keeps a hand near a weapon.","heroes":["h1","h12","h9","h13","h11","h2"],"parties":["p5","p2"],"loc":"cragtooth_warren"},{"id":"e446","day":20,"season":1,"sday":20,"kind":"omen_true","imp":2,"text":"Grandmother Skaldi turned the Ace of Pentacles for Matt five days ago. Matt found 3 silver since, where nobody would think to look.","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e447","day":20,"season":1,"sday":20,"kind":"talent","imp":2,"text":"Cade lets Andrew pick the target: a knot on a far pine. Dead centre. Andrew picks a harder one.","heroes":["h13","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e453","day":20,"season":1,"sday":20,"kind":"party_strain","imp":3,"text":"Trouble by the campfire: Jeff has started sleeping on the far side of the fire from the rest of The Green Hammers.","heroes":["h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e454","day":20,"season":1,"sday":20,"kind":"dream","imp":2,"text":"Still the plan, says Troy: to have five true friends. The friendships are still forming.","heroes":["h8"],"parties":[]}],"21":[{"id":"e457","day":21,"season":1,"sday":21,"kind":"night","imp":2,"text":"Matt follows strange lights away from the camp on the first floor of Frostspire, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e458","day":21,"season":1,"sday":21,"kind":"keystone","imp":2,"text":"'The worse it goes for Joshua, the better it goes for the rest of us,' says a partymate. Joshua is a Living Saint: his own worst moment in a fight heals the whole party.","heroes":["h11"],"parties":[],"ks":"Living Saint"},{"id":"e459","day":21,"season":1,"sday":21,"kind":"keystone","imp":2,"text":"One goblin falls, and Andrew is already into the next before it lands. Can't Stop Now: the moment he drops a foe, he crashes into another, often knocking it flat.","heroes":["h2"],"parties":[],"ks":"Can't Stop Now"},{"id":"e460","day":21,"season":1,"sday":21,"kind":"fight","imp":3,"text":"Cade hits hardest as the Royal Shadows see off 3 Kobolds and a Giant Bat in the sentry hole on the first floor of Cragtooth Warren: one Volley caught three of them at once. Whenever it looked bad, Keenan was already there. Loot: 6 silver each, 2 kobold firepeppers, 2 ore.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e461","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"Two Giant Bats and 2 Goblin Archers fall to the Royal Shadows in the new dig on the first floor of Cragtooth Warren. One Arcane Torrent from Joshua and two of them were on the ground. Joshua kept two of them busy so nobody else had to. Loot: 1 silver each, 2 fangs & claws, a pair of bat wings.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e465","day":21,"season":1,"sday":21,"kind":"keystone","imp":2,"text":"Harry loses a hand, wins a hand, and wears the same face for both. Poker Face: dealers rarely catch him cheating, he quits a losing game early, and on the road a bluff can leave a foe befuddled.","heroes":["h1"],"parties":[],"ks":"Poker Face"},{"id":"e466","day":21,"season":1,"sday":21,"kind":"keystone","imp":2,"text":"'The bards are still arguing about the distance,' says a tavern-goer, about Jeff. Shot Heard Round the Realm: one huge, crit-prone shot.","heroes":["h12"],"parties":[],"ks":"Shot Heard Round the Realm"},{"id":"e467","day":21,"season":1,"sday":21,"kind":"skim","imp":2,"text":"Jeff quietly pockets an extra 8 silver while The Green Hammers count the rest. Nobody notices.","heroes":["h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e470","day":21,"season":1,"sday":21,"kind":"wild_room","imp":3,"text":"Harry sang a drake in Cragtooth Warren to sleep and walked off with some of its heap. Music critics are calling it 'a sound career move.'","heroes":["h1","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e475","day":21,"season":1,"sday":21,"kind":"fight","imp":2,"text":"In the moon-howl hollow on the first floor of the Wolf Den, 2 Dire Wolves and 2 Wolves get in Tidal Riders' way, briefly. Amanda put everything into one Drain Life, and the dire wolf reeled. Loot: 5 pelts, 5 fangs & claws, 3 wolf haunches.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e476","day":21,"season":1,"sday":21,"kind":"bond","imp":2,"text":"Troy keeps the good chair at The Watching Oak for Amanda. Amanda keeps the last of the stew for Troy. Friends, then.","heroes":["h8","h17"],"parties":[],"loc":"wolf_den","bond":"friends"},{"id":"e477","day":21,"season":1,"sday":21,"kind":"gift","imp":2,"text":"Nothing goes to waste in this crew: Troy's old Wizard's Hat is Amanda's now.","heroes":["h8","h17"],"parties":["p4"],"loc":"wolf_den"},{"id":"e478","day":21,"season":1,"sday":21,"kind":"evolve","imp":4,"text":"Troy the Mage is an Illusionist now, after a career of sneaking and misdirection led by Phantasm and Blink. His first new trick is Puppet Strings, and the guild has sent a Top Hat and a Scrying Orb to go with it. It was close: Cleric was the other road.","heroes":["h8"],"parties":[],"cls_to":"illusionist"},{"id":"e482","day":21,"season":1,"sday":21,"kind":"keystone","imp":2,"text":"Corrine reaches level 10 and gains Chose the Ground. Every fight they're in happens where they decided it would.","heroes":["h7"],"parties":[],"ks":"Chose the Ground"},{"id":"e483","day":21,"season":1,"sday":21,"kind":"ambush","imp":2,"text":"On the road to the Greenwood, a Bandit gets in Corrine's way, briefly. Before Corrine's Thorn Whip it could have gone either way. Loot: 16 silver, a string of bandit sausages.","heroes":["h7"],"parties":[],"loc":"greenwood"},{"id":"e485","day":21,"season":1,"sday":21,"kind":"boss_race","imp":2,"text":"Back in the race for The Mimic King: The Royal Shadows, headed for Cragtooth Warren once more.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e486","day":21,"season":1,"sday":21,"kind":"song","imp":3,"text":"New at The Damp Lantern tonight: \"Hold Fast, Troy\", about the day Troy brought down Gruk the Warchief. The bard swears every word is true.","heroes":["h8"],"parties":[],"loc":"ashfen"},{"id":"e492","day":21,"season":1,"sday":21,"kind":"ability","imp":2,"text":"Keenan finds a library in Cragtooth Warren that the monsters have been using as a larder. He rescues the one readable shelf and comes out an expert on old drains, and calmer for it.","heroes":["h9"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e494","day":21,"season":1,"sday":21,"kind":"omen_true","imp":2,"text":"Sabine Venn turned the Two of Swords for Mark three days ago and went quiet. Mark hasn't won a fight or gone up a level since.","heroes":["h14"],"parties":[],"loc":"ashveil_crypts"},{"id":"e498","day":21,"season":1,"sday":21,"kind":"dream","imp":3,"text":"Ask Corrine what it's all for and the answer hasn't changed: master the craft, 10 new levels this season. She is nearly there, with 1 new level to go.","heroes":["h7"],"parties":[]},{"id":"e499","day":21,"season":1,"sday":21,"kind":"ambition","imp":5,"text":"Keenan has gained 10 levels this season, a true master of the craft, and nobody who knew him at the start would have bet on it. By morning he has a new dream: to set foot in six of the realm's towns.","heroes":["h9"],"parties":[]},{"id":"e501","day":21,"season":1,"sday":21,"kind":"ledger","imp":2,"text":"MARKET WEEK: 9 hauls sold across the realm, 264 silver all told. Biggest haul: Griffin, 67 silver in Thornwall. Back up from the deep: Tidal Riders (5 days in Goblin Camp), The Black Pack (3 days in Cragtooth Warren), The Royal Shadows (4 days in Cragtooth Warren).","heroes":["h5","h17","h14","h9"],"parties":["p4","p1","p2"]},{"id":"e502","day":21,"season":1,"sday":21,"kind":"contract","imp":2,"text":"The mayor's spectacles turn up on the mayor's own head, pushed up into his hair. The job to fetch them from Cragtooth Warren is quietly torn off the Ironhaven board, and The Black Pack is spared the trip.","heroes":["h14","h3","h10"],"parties":["p1"],"loc":"ironhaven"}],"22":[{"id":"e503","day":22,"season":1,"sday":22,"kind":"omen","imp":3,"text":"On day 18 a shepherd swore a hill moved, and Matt saw it first. Today something old woke under Goblin Camp. Matt called it, and everyone who laughed at the omen owes him a drink when he's back from Frostspire.","heroes":["h15"],"parties":[]},{"id":"e505","day":22,"season":1,"sday":22,"kind":"fight","imp":2,"text":"It's a Cave Troll against the Green Hammers in the troll's hollow on the bottom floor of Cragtooth Warren, and it isn't close. Harry's Poker Face had the cave troll briefly confused about whose side it was on. The others will say it was close. Harry made sure it wasn't. Loot: 8 silver each, 1 troll hide, 3 ore.","heroes":["h1","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e507","day":22,"season":1,"sday":22,"kind":"talent","imp":2,"text":"Harry sews a lucky charm into the lining of Jeff's coat. Jeff only finds it a week later.","heroes":["h1","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e508","day":22,"season":1,"sday":22,"kind":"evolve","imp":4,"text":"Allie the Mage is a Cryomancer now, after a career of frost led by Ice Wall and Frost Shard. Cold hands, colder stare. Her first new trick is Glacial Wall, and the guild has sent a Silver Circlet to go with it.","heroes":["h4"],"parties":[],"cls_to":"cryomancer"},{"id":"e510","day":22,"season":1,"sday":22,"kind":"fishing","imp":2,"text":"A first for the whole league: Katie pulls a silver roach at the King's Road ford and holds it up as proof.","heroes":["h16"],"parties":[],"loc":"kingsroad"},{"id":"e511","day":22,"season":1,"sday":22,"kind":"hunt","imp":2,"text":"The Greenwood: Corrine has the doe in a clear line, sees the fawn behind it, and lowers the bow. A hunter's choice and nobody's rule. The two walk on, light on their feet.","heroes":["h7"],"parties":[],"loc":"greenwood"},{"id":"e513","day":22,"season":1,"sday":22,"kind":"wild_room","imp":3,"text":"In the Wolf Den, Amanda read the bear-height tree and worked out when its owner last visited the larder. The wolves have never had so detailed a rumour about their neighbour.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e514","day":22,"season":1,"sday":22,"kind":"gear","imp":3,"text":"Behind a walled-up door beside the scratched tree on the first floor of the Wolf Den, Amanda finds a Sturdy Traveler's Garb and puts it straight on: +1.5 armour, and better than anything she could buy.","heroes":["h17"],"parties":["p4"],"loc":"wolf_den"},{"id":"e517","day":22,"season":1,"sday":22,"kind":"trap","imp":2,"text":"Matt springs icicles hung over a doorway in the icicle porch on the first floor of Frostspire (deep cut).","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e519","day":22,"season":1,"sday":22,"kind":"party_life","imp":3,"text":"Joshua told The Royal Shadows to carry on without him from the first floor. A minute of honest thought later, the whole crew turned for daylight.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e520","day":22,"season":1,"sday":22,"kind":"delve_done","imp":3,"text":"After 3 days underground, The Royal Shadows climb out of Cragtooth Warren gulping the open air like water: 10 rooms worked on the first floor, the bat roost and a walled-up room found, and 116 silver between them.","heroes":["h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e525","day":22,"season":1,"sday":22,"kind":"mood","imp":2,"text":"Alone on the first floor of Frostspire, Matt straightens a frozen tapestry that was already straight, and then another that wasn't.","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e526","day":22,"season":1,"sday":22,"kind":"mood","imp":2,"text":"Amanda scrubs the same pot until there's no pot left to speak of.","heroes":["h17"],"parties":[],"loc":"wolf_den"},{"id":"e527","day":22,"season":1,"sday":22,"kind":"song","imp":3,"text":"A fiddler at The Watching Oak plays \"Allie, Allie, Bring the Silver Home\" for the first time, a song about the road Allie's crew finally finished. Somebody at the back asks for it again before it's even over.","heroes":["h4"],"parties":[],"loc":"hollowood"},{"id":"e531","day":22,"season":1,"sday":22,"kind":"omen_true","imp":2,"text":"Five days ago, Sabine Venn promised Morgan a warm welcome. Morgan has been made welcome somewhere new since.","heroes":["h18"],"parties":[],"loc":"ashveil_crypts"},{"id":"e532","day":22,"season":1,"sday":22,"kind":"fishing","imp":2,"text":"The books show no Brown Trout until today, when Katie lands one at the King's Road ford.","heroes":["h16"],"parties":[],"loc":"kingsroad"},{"id":"e533","day":22,"season":1,"sday":22,"kind":"night_game","imp":2,"text":"Word spreads of a song by the fire: Harry led \"The Star-Counter's Tune\", and those who heard it are still talking about it.","heroes":["h1","h12"],"parties":[],"loc":"cragtooth_warren"},{"id":"e537","day":22,"season":1,"sday":22,"kind":"pet","imp":2,"text":"Jeff sits a long time in the dark. Nugget sits with him. Neither says anything, which helps.","heroes":["h12"],"parties":[],"loc":"cragtooth_warren"},{"id":"e538","day":22,"season":1,"sday":22,"kind":"goal_progress","imp":2,"text":"Morgan is getting close: earn 100 silver before the season ends (82 of 100 silver).","heroes":["h18"],"parties":[]}],"23":[{"id":"e540","day":23,"season":1,"sday":23,"kind":"underdog","imp":3,"text":"UNDERDOG WATCH: Mark sits 16th of 17, and the Crier isn't worried. Remember day 8 of season 1, when The Black Pack saw off 2 Bandits on the King's Road? The money's on a comeback.","heroes":["h14"],"parties":[]},{"id":"e543","day":23,"season":1,"sday":23,"kind":"party_life","imp":3,"text":"Matt told Frostspire out loud that it had won, then left by the only sensible door on the first floor.","heroes":["h15"],"parties":[],"loc":"frostspire"},{"id":"e546","day":23,"season":1,"sday":23,"kind":"fight","imp":2,"text":"In the kobold nursery on the bottom floor of Cragtooth Warren, 4 Kobolds get in the Green Hammers' way, briefly. Ask anyone when it turned: Harry's Arc Lightning. Jeff dropped four of them, Shot Heard Round the Realm doing most of the work. Loot: 11 silver each, 1 ore, 2 trinkets.","heroes":["h1","h12"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e548","day":23,"season":1,"sday":23,"kind":"evolve","imp":4,"text":"Katie the Warrior is a Berserker now. A career heavy on fury does that, and Cleave led the way. Her first new trick is Berserk, and the guild sends over a Horned Helm to go with it. Shirt optional, restraint absent.","heroes":["h16"],"parties":[],"cls_to":"berserker"},{"id":"e550","day":23,"season":1,"sday":23,"kind":"fishing","imp":3,"text":"At the King's Road ford, Katie held The Ford Ghost for twenty heartbeats. The line did not. The legend swims on.","heroes":["h16"],"parties":[],"loc":"kingsroad"},{"id":"e552","day":23,"season":1,"sday":23,"kind":"town_life","imp":2,"text":"An old adventurer in Ironhaven tells Keenan three mistakes they made. Keenan writes them down. The old adventurer is delighted at the notebook.","heroes":["h9"],"parties":[],"loc":"ironhaven"},{"id":"e553","day":23,"season":1,"sday":23,"kind":"town_life","imp":2,"text":"Andrew is swept into a marble-floor Ironhaven dinner with the Varro brothers and Prelate Gaudin. It is the finest evening anyone can remember, and nobody can say how it happened.","heroes":["h2"],"parties":[],"loc":"ironhaven"},{"id":"e554","day":23,"season":1,"sday":23,"kind":"mount","imp":4,"text":"Something starts following Ryan through the Ashveil Crypts: a horse made of bones, with its saddle still on. It stops when Ryan stops. Ryan names it Hollow.","heroes":["h3"],"parties":[],"loc":"ashveil_crypts"},{"id":"e557","day":23,"season":1,"sday":23,"kind":"party_life","imp":3,"text":"On the first floor of the Wolf Den, Amanda sat down and offered to mind the bags. There were no bags to mind, and Tidal Riders turned for the stairs regardless.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e558","day":23,"season":1,"sday":23,"kind":"delve_done","imp":3,"text":"After 5 days, Tidal Riders come back into the light with the dark in every seam. They reached the Wolf Den's deepest floor, took 15 rooms off the blank side of the map and put 90% of it on paper. They found a hidden room behind the game trail, the moon-howl hollow and a walled-up room beside the scratched tree, split 7","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"wolf_den"},{"id":"e559","day":23,"season":1,"sday":23,"kind":"mood","imp":2,"text":"Harry asks how far it is back to daylight, and an hour later asks again, and nods at the answer as if it were new.","heroes":["h1"],"parties":[],"loc":"cragtooth_warren"},{"id":"e560","day":23,"season":1,"sday":23,"kind":"mood","imp":2,"text":"Jeff flinches when someone claps him on the shoulder, then apologises for flinching.","heroes":["h12"],"parties":[],"loc":"cragtooth_warren"},{"id":"e561","day":23,"season":1,"sday":23,"kind":"race","imp":4,"text":"THE RACE, 7 days left: Matt 263, Keenan 171, Troy 157. Matt leads by 92, so Keenan needs a big week. Matt's season so far: 84 from levels and 50 from silver earned.","heroes":["h15","h9","h8"],"parties":[]},{"id":"e562","day":23,"season":1,"sday":23,"kind":"song","imp":3,"text":"At The Sagging Beam, two bards argue over who wrote \"Hollowood Never Saw Katie Coming\", a song about the road Katie's crew finally finished, boring bits left out. Both sing it. The room prefers the second.","heroes":["h16"],"parties":[],"loc":"thornwall"},{"id":"e565","day":23,"season":1,"sday":23,"kind":"bond","imp":4,"text":"Allie and Katie are best friends now. They finish each other's sentences, badly.","heroes":["h4","h16"],"parties":[],"loc":"kingsroad","bond":"best friends"},{"id":"e567","day":23,"season":1,"sday":23,"kind":"party_leave","imp":3,"text":"Jeff leaves The Green Hammers. He needs time away from all of it.","heroes":["h12","h1"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e568","day":23,"season":1,"sday":23,"kind":"party_disband","imp":4,"text":"After 19 days The Green Hammers disband. With only one member left, there is no party to speak of.","heroes":["h1"],"parties":["p5"],"loc":"cragtooth_warren"},{"id":"e569","day":23,"season":1,"sday":23,"kind":"dream","imp":2,"text":"A fortune teller asks Griffin what Griffin wants. Easy: to make a fortune (2,000 silver earned). 205 of 2,000 silver, and counting.","heroes":["h5"],"parties":[]},{"id":"e571","day":23,"season":1,"sday":23,"kind":"aside","imp":3,"text":"In an Ironhaven tavern, Cade carves the party's name into a table: small, in the corner, where only they'll find it.","heroes":["h13"],"parties":[],"loc":"ironhaven"}],"24":[{"id":"e576","day":24,"season":1,"sday":24,"kind":"gear","imp":2,"text":"Jeff trades up to a Longbow from Bertil Hammerhand (150 silver).","heroes":["h12"],"parties":[],"loc":"ironhaven"},{"id":"e579","day":24,"season":1,"sday":24,"kind":"talent","imp":2,"text":"Keenan buries flat stones under the coals and lays the bedrolls over them. Cade sleeps like a cat on a hearth.","heroes":["h9","h13"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e580","day":24,"season":1,"sday":24,"kind":"road","imp":3,"text":"At the Snow Lamp, an old pilgrim tells Matt the flame was lit by the first traveller ever to cross the pass and has never gone out since. Matt leaves 2 copper to keep it burning.","heroes":["h15"],"parties":[]},{"id":"e581","day":24,"season":1,"sday":24,"kind":"night","imp":2,"text":"Matt trades a ration with a stranger who wasn't there at dusk and isn't there at dawn. The trinket stays.","heroes":["h15"],"parties":[],"loc":"whitepeak"},{"id":"e584","day":24,"season":1,"sday":24,"kind":"ambush","imp":2,"text":"Corrine defeats a Wolf on the road to Hollowood without much fuss. The wolf was already dying of Corrine's Thorn Whip before it knew it. Loot: 1 pelt, 1 fang, a wolf haunch.","heroes":["h7"],"parties":[],"loc":"greenwood"},{"id":"e585","day":24,"season":1,"sday":24,"kind":"road","imp":3,"text":"On the road to Hollowood, a raven tells Corrine something about Goblin Camp in a voice like an old man's, then flies off before Corrine can ask a single thing.","heroes":["h7"],"parties":[]},{"id":"e586","day":24,"season":1,"sday":24,"kind":"town_life","imp":2,"text":"In the Watching Oak, an old sailor swears to an exact dragon, with colours and dates. Corrine listens through the sailor's third ale and takes notes. The notes are useful.","heroes":["h7"],"parties":[],"loc":"hollowood"},{"id":"e587","day":24,"season":1,"sday":24,"kind":"night_game","imp":2,"text":"The bandit steps out on the road to Hollowood with a hopeful expression and a well-worn set of Crooked Cards, and nobody can quite bring themselves to draw a blade. The bandit reads the final board three times, shrugs and hands Troy Bandit's Hidden Coin, saying it was meant to be a good one. Amanda says nobody has ever been so politely held up, and is not sure how to feel about it.","heroes":["h17","h8","h5"],"parties":["p4"],"loc":"hollowood"},{"id":"e588","day":24,"season":1,"sday":24,"kind":"fishing","imp":2,"text":"Griffin lands a mere carp at the Wolfwater ferry, the first the league has ever seen. The anglers will want to hear about it.","heroes":["h5"],"parties":[],"loc":"greenwood"},{"id":"e592","day":24,"season":1,"sday":24,"kind":"mount","imp":2,"text":"Troy spends 14 silver in Hollowood on a pony called Muffin, and rides it twice round the square before anyone can stop him.","heroes":["h8"],"parties":[],"loc":"hollowood"},{"id":"e595","day":24,"season":1,"sday":24,"kind":"gear","imp":2,"text":"After an hour of haggling, Harry leaves Ironhaven with a Silver Lute for 121 silver, 18 under the asking price. Bertil Hammerhand calls it robbery.","heroes":["h1"],"parties":[],"loc":"ironhaven"},{"id":"e597","day":24,"season":1,"sday":24,"kind":"gambling","imp":2,"text":"Clerk Odalric writes 94 silver in Jeff's account and underlines it in red.","heroes":["h12"],"parties":[],"loc":"ironhaven"},{"id":"e598","day":24,"season":1,"sday":24,"kind":"party_formed","imp":4,"text":"Jeff and Harry shake on it at The Gilded Flagon and become The Rose Ledger. Predatory, by the look of them.","heroes":["h12","h1"],"parties":["p6"],"loc":"ironhaven"},{"id":"e599","day":24,"season":1,"sday":24,"kind":"drinking","imp":2,"text":"Drinking contest at The Watching Oak: Griffin wins. Corrine sings. Badly. For an hour.","heroes":["h5","h7"],"parties":[],"loc":"hollowood"},{"id":"e600","day":24,"season":1,"sday":24,"kind":"party_join","imp":3,"text":"Over a table in Hollowood, Corrine signs on with Tidal Riders. That makes 4.","heroes":["h7","h17","h8","h5"],"parties":["p4"],"loc":"hollowood"},{"id":"e601","day":24,"season":1,"sday":24,"kind":"meet","imp":2,"text":"Jeff spots The Royal Shadows on the road between Cragtooth Warren and Ironhaven, and suddenly everybody has urgent business with the bottom of a pack.","heroes":["h12","h9","h13","h11","h2"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e603","day":24,"season":1,"sday":24,"kind":"night_game","imp":2,"text":"A rivalry is born at camp in the Ashveil Crypts: Mark beats Olivia at chess, and the record stands at 3-0.","heroes":["h14","h10"],"parties":[],"loc":"ashveil_crypts"},{"id":"e604","day":24,"season":1,"sday":24,"kind":"argument","imp":2,"text":"Ryan and Olivia spend supper disagreeing about who gets the dry side of the fire, politely at first.","heroes":["h3","h10"],"parties":["p1"]},{"id":"e605","day":24,"season":1,"sday":24,"kind":"pet","imp":2,"text":"Clementine and Pickles become fast friends at the Ashveil Crypts. Their owners, Olivia and Ryan, have no choice but to follow suit.","heroes":["h10","h3"],"parties":[],"loc":"ashveil_crypts"},{"id":"e606","day":24,"season":1,"sday":24,"kind":"pet","imp":2,"text":"Joshua slips Waffles a scrap from supper. Waffles will now follow Joshua to the ends of the realm. Cade has noticed.","heroes":["h13","h11"],"parties":[],"loc":"cragtooth_warren"},{"id":"e607","day":24,"season":1,"sday":24,"kind":"bond","imp":2,"text":"Some people take a season to get on. Griffin and Corrine took about one drink at The Watching Oak.","heroes":["h5","h7"],"parties":[],"loc":"hollowood","bond":"friends"},{"id":"e608","day":24,"season":1,"sday":24,"kind":"dream","imp":3,"text":"To nobody in particular, Allie raises a cup tonight to the season's dream: master the craft and gain 10 levels. 2 new levels left, close enough to taste.","heroes":["h4"],"parties":[]},{"id":"e609","day":24,"season":1,"sday":24,"kind":"epithet","imp":3,"text":"The name sticks: Harry Dice. Harry pretends to hate it.","heroes":["h1"],"parties":[]},{"id":"e610","day":24,"season":1,"sday":24,"kind":"epithet","imp":3,"text":"Jeff the Lucky, they're calling him now, and it sticks. Jeff pretends to hate it.","heroes":["h12"],"parties":[]}]};